	switch strategy {
	case string(ResourceMerge):
		return ResourceMerge, nil
	case string(FastForward):
		return FastForward, nil
	case string(ForceDeleteReplace):
		return ForceDeleteReplace, nil
	case string(CopyMerge):
		return CopyMerge, nil
	default:
		return "", fmt.Errorf("unknown update strategy %q", strategy)
	}
}
","id":"SRC-CU-c472430e7de98524","kind":"SOURCE_SPAN","locator":{"column_start":1,"end_line":121,"path":"api/kptfile/v1/types.go","start_line":108},"origin":"selected candidate CU-c472430e7de98524","snapshot_id":"549777ce5a6794c45f726f2dd284384bd01106ce8d67f6e66395b3f57791cfc3"},{"content_digest":"6047ccaad7c2dcd0545fd7e992cc1fa15d37da71eb38010751508c7611e46b4b","excerpt":"func (pn *pkgNode) runPipeline(ctx context.Context, hctx *hydrationContext, input []*yaml.RNode) ([]*yaml.RNode, error) {
	const op errors.Op = "pipeline.run"

	hctx.runnerOptions.FullDisplayName = resolveFullDisplayName(pn.pkg, hctx.runnerOptions.LogOptions)

	pr := printer.FromContextOrDie(ctx)
	// TODO: the DisplayPath is a relative file path. It cannot represent the
	//       package structure. We should have function to get the relative package
	//       path here.
	// ^^^^^ did they mean something like pn.pkg.UniquePath.RelativePath()?
	prOpts := printer.NewOpt().
		Path(pn.pkg.UniquePath).
		DisplayPath(pn.pkg.DisplayPath).
		DisplayName(hctx.runnerOptions.FullDisplayName)
	pr.OptPrintf(prOpts, "\n")

	pl, err := pn.pkg.Pipeline()
	if err != nil {
		return nil, err
	}

	if pl.IsEmpty() {
		if err := kptfilev1.AreKRM(input); err != nil {
			return nil, fmt.Errorf("input resource list must contain only KRM resources: %w", err)
		}
		return input, nil
	}

	// perform runtime validation for pipeline
	if err := pn.pkg.ValidatePipeline(); err != nil {
		return nil, err
	}

	mutatedResources, err := pn.runMutators(ctx, hctx, input)
	if err != nil {
		return mutatedResources, errors.E(op, hctx.runnerOptions.FullDisplayName, pn.pkg.UniquePath, err)
	}

	if err = pn.runValidators(ctx, hctx, mutatedResources); err != nil {
		return mutatedResources, errors.E(op, hctx.runnerOptions.FullDisplayName, pn.pkg.UniquePath, err)
	}

	pr.Printf("\n")

	return mutatedResources, nil
}
","id":"SRC-CU-b185a6639d1920f7","kind":"SOURCE_SPAN","locator":{"column_start":1,"end_line":749,"path":"pkg/lib/kptops/render_executor.go","start_line":704},"origin":"selected candidate CU-b185a6639d1920f7","snapshot_id":"549777ce5a6794c45f726f2dd284384bd01106ce8d67f6e66395b3f57791cfc3"},{"content_digest":"2779d41d4f783345fc2cc14d421d77faaf9b2ef8547dc60d6ef225f0683cf4c1","excerpt":"func NewRunner(ctx context.Context, parent string) *Runner {
