		"allow wasm to be used during pipeline execution.")
	cmdutil.FixDocs("kpt", parent, c)
	r.Command = c
	return r
}
","id":"SRC-CU-77c1b8b4dc03693e","kind":"SOURCE_SPAN","locator":{"column_start":1,"end_line":72,"path":"commands/fn/render/cmdrender.go","start_line":37},"origin":"selected candidate CU-77c1b8b4dc03693e","snapshot_id":"549777ce5a6794c45f726f2dd284384bd01106ce8d67f6e66395b3f57791cfc3"},{"content_digest":"83390a5cff5e24f224f265fcb7d91ba583c823360003014c5775725b5561f61c","excerpt":"func (pn *pkgNode) refreshFnConfig(runner *fnruntime.FunctionRunner, input []*yaml.RNode, configPath string) error {
	if configPath == "" {
		return nil
	}
	for _, r := range input {
		pkgPath, err := pkg.GetPkgPathAnnotation(r)
		if err != nil {
			return err
		}
		currPath, _, err := kioutil.GetFileAnnotations(r)
		if err != nil {
			return err
		}
		if pkgPath == pn.pkg.UniquePath.String() && currPath == configPath {
			runner.SetFnConfig(r)
			break
		}
	}
	return nil
}
